  1→/**
  2→ * OAuth subscription management routes.
  3→ *
  4→ * Handles OAuth flow for subscription-based LLM providers (Anthropic Claude Pro, etc.)
  5→ */
  6→
  7→import { Router } from "express";
  8→import type { Request, Response } from "express";
  9→import { requireAuth } from "../auth/middleware.js";
 10→import { OAuthService } from "../services/oauth-service.js";
 11→import type { CryptoService } from "../services/crypto.js";
 12→import { getDatabase } from "../db/index.js";
 13→import { generatePKCE } from "../utils/pkce.js";
 14→
 15→// OAuth provider configurations
 16→// OpenAI redirect URI: must match a URI registered with the OAuth client.
 17→// The public CLI client only allows http://localhost:1455/auth/callback.
 18→// For cloud deployment with a custom OAuth client, override via OAUTH_OPENAI_REDIRECT_URI.
 19→const OPENAI_REDIRECT_URI =
 20→	process.env.OAUTH_OPENAI_REDIRECT_URI || "http://localhost:1455/auth/callback";
 21→
 22→const ANTIGRAVITY_REDIRECT_URI =
 23→	process.env.OAUTH_ANTIGRAVITY_REDIRECT_URI || "http://localhost:51121/oauth-callback";
 24→
 25→const OAUTH_PROVIDERS: Record<
 26→	string,
 27→	{
 28→		clientId: string;
 29→		clientSecret?: string;
 30→		authorizeUrl: string;
 31→		tokenUrl: string;
 32→		redirectUri: string;
 33→		scopes: string;
 34→	}
 35→> = {
 36→	anthropic: {
 37→		clientId: "9d1c250a-e61b-44d9-88ed-5944d1962f5e",
 38→		authorizeUrl: "https://claude.ai/oauth/authorize",
 39→		tokenUrl: "https://console.anthropic.com/v1/oauth/token",
 40→		redirectUri: "https://console.anthropic.com/oauth/code/callback",
 41→		scopes: "org:create_api_key user:profile user:inference",
 42→	},
 43→	"openai-codex": {
 44→		clientId: "app_EMoamEEZ73f0CkXaXp7hrann",
 45→		authorizeUrl: "https://auth.openai.com/oauth/authorize",
 46→		tokenUrl: "https://auth.openai.com/oauth/token",
 47→		redirectUri: OPENAI_REDIRECT_URI,
 48→		scopes: "openid profile email offline_access",
 49→	},
 50→	"google-antigravity": {
 51→		// Requires OAUTH_GOOGLE_CLIENT_ID and OAUTH_GOOGLE_CLIENT_SECRET env vars.
 52→		// Use the well-known public Cloud Shell / Gemini Code Assist OAuth client
 53→		// credentials (see .env.development.example).
 54→		clientId: process.env.OAUTH_GOOGLE_CLIENT_ID || "",
 55→		clientSecret: process.env.OAUTH_GOOGLE_CLIENT_SECRET || "",
 56→		authorizeUrl: "https://accounts.google.com/o/oauth2/v2/auth",
 57→		tokenUrl: "https://oauth2.googleapis.com/token",
 58→		redirectUri: ANTIGRAVITY_REDIRECT_URI,
 59→		scopes: [
 60→			"https://www.googleapis.com/auth/cloud-platform",
 61→			"https://www.googleapis.com/auth/userinfo.email",
 62→			"https://www.googleapis.com/auth/userinfo.profile",
 63→			"https://www.googleapis.com/auth/cclog",
 64→			"https://www.googleapis.com/auth/experimentsandconfigs",
 65→		].join(" "),
 66→	},
 67→};
 68→
 69→/** Discover the Antigravity project ID for the authenticated user. */
 70→async function discoverAntigravityProject(accessToken: string): Promise<string> {
 71→	const DEFAULT_PROJECT_ID = "rising-fact-p41fc";
 72→	const headers = {
 73→		Authorization: `Bearer ${accessToken}`,
 74→		"Content-Type": "application/json",
 75→		"User-Agent": "google-api-nodejs-client/9.15.1",
 76→		"X-Goog-Api-Client": "google-cloud-sdk vscode_cloudshelleditor/0.1",
 77→		"Client-Metadata": JSON.stringify({
 78→			ideType: "IDE_UNSPECIFIED",
 79→			platform: "PLATFORM_UNSPECIFIED",
 80→			pluginType: "GEMINI",
 81→		}),
 82→	};
 83→	const body = JSON.stringify({
 84→		metadata: { ideType: "IDE_UNSPECIFIED", platform: "PLATFORM_UNSPECIFIED", pluginType: "GEMINI" },
 85→	});
 86→
 87→	for (const endpoint of [
 88→		"https://cloudcode-pa.googleapis.com",
 89→		"https://daily-cloudcode-pa.sandbox.googleapis.com",
 90→	]) {
 91→		try {
 92→			const res = await fetch(`${endpoint}/v1internal:loadCodeAssist`, { method: "POST", headers, body });
 93→			if (!res.ok) continue;
 94→			const data = (await res.json()) as {
 95→				cloudaicompanionProject?: string | { id?: string };
 96→			};
 97→			if (typeof data.cloudaicompanionProject === "string" && data.cloudaicompanionProject) {
 98→				return data.cloudaicompanionProject;
 99→			}
100→			if (
101→				data.cloudaicompanionProject &&
102→				typeof data.cloudaicompanionProject === "object" &&
103→				data.cloudaicompanionProject.id
104→			) {
105→				return data.cloudaicompanionProject.id;
106→			}
107→		} catch {
108→			// try next endpoint
109→		}
110→	}
111→	return DEFAULT_PROJECT_ID;
112→}
113→
114→// Temporary storage for PKCE verifiers (in production, use Redis)
115→const pkceStorage = new Map<string, { verifier: string; userId: string; expiresAt: number }>();
116→
117→// Clean up expired PKCE entries every 10 minutes
118→setInterval(() => {
119→	const now = Date.now();
120→	for (const [key, value] of pkceStorage.entries()) {
121→		if (value.expiresAt < now) {
122→			pkceStorage.delete(key);
123→		}
124→	}
125→}, 10 * 60 * 1000);
126→
127→export function createOAuthRouter(crypto: CryptoService): Router {
128→	const router = Router();
129→	const db = getDatabase();
130→	// @ts-expect-error Database wrapper is compatible with Pool for OAuthService usage
131→	const oauthService = new OAuthService(db, crypto);
132→
133→	// All routes require authentication
134→	router.use(requireAuth);
135→
136→	// -----------------------------------------------------------------------
137→	// POST /:provider/start — Start OAuth flow for any provider
138→	// -----------------------------------------------------------------------
139→	router.post("/:provider/start", async (req: Request, res: Response) => {
140→		try {
141→			const { provider } = req.params;
142→			const userId = req.user!.userId;
143→
144→			// Validate provider
145→			// @ts-expect-error Express 5 params type is string | string[]
146→			if (!(provider in OAUTH_PROVIDERS)) {
147→				res.status(400).json({ success: false, error: "Unsupported provider" });
148→				return;
149→			}
150→
151→			const config = OAUTH_PROVIDERS[provider as keyof typeof OAUTH_PROVIDERS];
152→
153→			// Generate PKCE challenge
154→			const { verifier, challenge } = await generatePKCE();
155→
156→			// Store verifier temporarily (expires in 10 minutes)
157→			const stateKey = `${provider}-${userId}-${Date.now()}`;
158→			pkceStorage.set(stateKey, {
159→				verifier,
160→				userId,
161→				expiresAt: Date.now() + 10 * 60 * 1000,
162→			});
163→
164→			// Build authorization URL
165→			const authParams = new URLSearchParams({
166→				client_id: config.clientId,
167→				response_type: "code",
168→				redirect_uri: config.redirectUri,
169→				scope: config.scopes,
170→				code_challenge: challenge,
171→				code_challenge_method: "S256",
172→				state: stateKey,
173→			});
174→
175→			// Provider-specific parameters
176→			if (provider === "openai-codex") {
177→				authParams.set("codex_cli_simplified_flow", "true");
178→				authParams.set("id_token_add_organizations", "true");
179→				authParams.set("originator", "pi");
180→			} else if (provider === "google-antigravity") {
181→				authParams.set("access_type", "offline");
182→				authParams.set("prompt", "consent");
183→			}
184→
185→			const authUrl = `${config.authorizeUrl}?${authParams.toString()}`;
186→
187→			res.json({
188→				success: true,
189→				data: {
190→					authUrl,
191→					state: stateKey,
192→				},
193→			});
194→		} catch (err) {
195→			console.error(`[oauth] POST /:provider/start error:`, err);
196→			res.status(500).json({ success: false, error: "Failed to start OAuth flow" });
197→		}
198→	});
199→
200→	// -----------------------------------------------------------------------
201→	// POST /:provider/callback — Handle OAuth callback with authorization code
202→	// -----------------------------------------------------------------------
203→	router.post("/:provider/callback", async (req: Request, res: Response) => {
204→		try {
205→			const { provider } = req.params;
206→			const { code, state } = req.body;
207→			const userId = req.user!.userId;
208→
209→			// Validate provider
210→			// @ts-expect-error Express 5 params type is string | string[]
211→			if (!(provider in OAUTH_PROVIDERS)) {
212→				res.status(400).json({ success: false, error: "Unsupported provider" });
213→				return;
214→			}
215→
216→			if (!code || typeof code !== "string") {
217→				res.status(400).json({ success: false, error: "code is required" });
218→				return;
219→			}
220→			if (!state || typeof state !== "string") {
221→				res.status(400).json({ success: false, error: "state is required" });
222→				return;
223→			}
224→
225→			// Retrieve and validate PKCE verifier
226→			const pkceData = pkceStorage.get(state);
227→			if (!pkceData) {
228→				res.status(400).json({ success: false, error: "Invalid or expired state" });
229→				return;
230→			}
231→			if (pkceData.userId !== userId) {
232→				res.status(403).json({ success: false, error: "State does not match user" });
233→				return;
234→			}
235→
236→			// Clean up PKCE storage
237→			pkceStorage.delete(state);
238→
239→			const config = OAUTH_PROVIDERS[provider as keyof typeof OAUTH_PROVIDERS];
240→
241→			// Exchange code for tokens
242→			const tokenParams: Record<string, string> = {
243→				grant_type: "authorization_code",
244→				client_id: config.clientId,
245→				code: code,
246→				redirect_uri: config.redirectUri,
247→				code_verifier: pkceData.verifier,
248→			};
249→			if (config.clientSecret) {
250→				tokenParams.client_secret = config.clientSecret;
251→			}
252→
253→			const tokenResponse = await fetch(config.tokenUrl, {
254→				method: "POST",
255→				headers: {
256→					"Content-Type": "application/x-www-form-urlencoded",
257→				},
258→				body: new URLSearchParams(tokenParams),
259→			});
260→
261→			if (!tokenResponse.ok) {
262→				const error = await tokenResponse.text();
263→				console.error(`[oauth] Token exchange failed for ${provider}:`, error);
264→				res.status(400).json({ success: false, error: "Token exchange failed" });
265→				return;
266→			}
267→
268→			const tokenData = (await tokenResponse.json()) as {
269→				access_token: string;
270→				refresh_token: string;
271→				expires_in: number;
272→			};
273→
274→			// Calculate expiry time (current time + expires_in seconds - 5 min buffer)
275→			const expiresAt = Date.now() + tokenData.expires_in * 1000 - 5 * 60 * 1000;
276→
277→			// Build credentials object (with provider-specific extra fields)
278→			const credentials: Record<string, unknown> = {
279→				refresh: tokenData.refresh_token,
280→				access: tokenData.access_token,
281→				expires: expiresAt,
282→			};
283→
284→			// Antigravity requires project discovery after token exchange
285→			if (provider === "google-antigravity") {
286→				credentials.projectId = await discoverAntigravityProject(tokenData.access_token);
287→				console.log(`[oauth] Antigravity project: ${credentials.projectId}`);
288→			}
289→
290→			// Store credentials
291→			await oauthService.storeCredentials(provider as any, credentials as any, { userId });
292→
293→			res.json({
294→				success: true,
295→				data: {
296→					provider,
297→					expiresAt: new Date(expiresAt).toISOString(),
298→				},
299→			});
300→		} catch (err) {
301→			console.error(`[oauth] POST /:provider/callback error:`, err);
302→			res.status(500).json({ success: false, error: "Failed to complete OAuth flow" });
303→		}
304→	});
305→
306→	// -----------------------------------------------------------------------
307→	// GET /:provider/status — Check if user has OAuth credentials for provider
308→	// -----------------------------------------------------------------------
309→	router.get("/:provider/status", async (req: Request, res: Response) => {
310→		try {
311→			const { provider } = req.params;
312→			const userId = req.user!.userId;
313→
314→			const credentials = await oauthService.getCredentials(provider as any, { userId });
315→
316→			if (!credentials) {
317→				res.json({
318→					success: true,
319→					data: {
320→						connected: false,
321→					},
322→				});
323→				return;
324→			}
325→
326→			res.json({
327→				success: true,
328→				data: {
329→					connected: true,
330→					expiresAt: new Date(credentials.expires).toISOString(),
331→					expired: credentials.expires < Date.now(),
332→				},
333→			});
334→		} catch (err) {
335→			console.error(`[oauth] GET /:provider/status error:`, err);
336→			res.status(500).json({ success: false, error: "Failed to check OAuth status" });
337→		}
338→	});
339→
340→	// -----------------------------------------------------------------------
341→	// DELETE /:provider — Disconnect OAuth for provider
342→	// -----------------------------------------------------------------------
343→	router.delete("/:provider", async (req: Request, res: Response) => {
344→		try {
345→			const { provider } = req.params;
346→			const userId = req.user!.userId;
347→
348→			const deleted = await oauthService.deleteCredentials(provider as any, { userId });
349→
350→			if (!deleted) {
351→				res.status(404).json({ success: false, error: "No OAuth credentials found" });
352→				return;
353→			}
354→
355→			res.json({ success: true });
356→		} catch (err) {
357→			console.error(`[oauth] DELETE /:provider error:`, err);
358→			res.status(500).json({ success: false, error: "Failed to disconnect OAuth" });
359→		}
360→	});
361→
362→	// -----------------------------------------------------------------------
363→	// GET / — List all OAuth connections for user
364→	// -----------------------------------------------------------------------
365→	router.get("/", async (req: Request, res: Response) => {
366→		try {
367→			const userId = req.user!.userId;
368→
369→			const credentials = await oauthService.listCredentials({ userId });
370→
371→			res.json({
372→				success: true,
373→				data: {
374→					credentials: credentials.map((cred) => ({
375→						provider: cred.provider,
376→						expiresAt: cred.expiresAt.toISOString(),
377→						expired: cred.expiresAt.getTime() < Date.now(),
378→						createdAt: cred.createdAt.toISOString(),
379→						updatedAt: cred.updatedAt.toISOString(),
380→					})),
381→				},
382→			});
383→		} catch (err) {
384→			console.error("[oauth] GET / error:", err);
385→			res.status(500).json({ success: false, error: "Failed to list OAuth credentials" });
386→		}
387→	});
388→
389→	return router;
390→}
