  1→/**
  2→ * OAuth credential management service.
  3→ *
  4→ * Handles storage, retrieval, and automatic refresh of OAuth credentials
  5→ * for subscription-based LLM providers (Anthropic Claude Pro, OpenAI Codex, etc.)
  6→ */
  7→
  8→import type { Pool } from "pg";
  9→import type { CryptoService } from "./crypto.js";
 10→import { getOAuthApiKey } from "@mariozechner/pi-ai/oauth";
 11→
 12→export interface OAuthCredentials {
 13→	refresh: string;
 14→	access: string;
 15→	expires: number; // Expiration timestamp in milliseconds
 16→	[key: string]: unknown;
 17→}
 18→
 19→export interface StoredOAuthCredential {
 20→	id: string;
 21→	userId?: string;
 22→	teamId?: string;
 23→	provider: string;
 24→	expiresAt: Date;
 25→	createdAt: Date;
 26→	updatedAt: Date;
 27→}
 28→
 29→interface OAuthCredentialRow {
 30→	id: string;
 31→	user_id?: string;
 32→	team_id?: string;
 33→	provider: string;
 34→	encrypted_dek: Buffer;
 35→	encrypted_refresh: Buffer;
 36→	encrypted_access: Buffer;
 37→	iv: Buffer;
 38→	expires_at: Date;
 39→	key_version: number;
 40→	created_at: Date;
 41→	updated_at: Date;
 42→}
 43→
 44→export type OAuthProviderId =
 45→	| "anthropic"
 46→	| "openai-codex"
 47→	| "github-copilot"
 48→	| "google-gemini-cli"
 49→	| "google-antigravity";
 50→
 51→export class OAuthService {
 52→	constructor(
 53→		private db: Pool,
 54→		private crypto: CryptoService,
 55→	) {}
 56→
 57→	/**
 58→	 * Store OAuth credentials for a user or team.
 59→	 * Credentials are encrypted using envelope encryption.
 60→	 */
 61→	async storeCredentials(
 62→		provider: OAuthProviderId,
 63→		credentials: OAuthCredentials,
 64→		options: { userId?: string; teamId?: string },
 65→	): Promise<void> {
 66→		if (!options.userId && !options.teamId) {
 67→			throw new Error("Either userId or teamId must be provided");
 68→		}
 69→		if (options.userId && options.teamId) {
 70→			throw new Error("Cannot specify both userId and teamId");
 71→		}
 72→
 73→		// Encrypt all credential fields as a single blob so they share the same DEK/IV.
 74→		// The encrypted_refresh column stores the combined blob; encrypted_access
 75→		// is set to an empty buffer (kept for schema compatibility).
 76→		// Extra fields (e.g. projectId for Antigravity) are preserved.
 77→		const combined = JSON.stringify(credentials);
 78→		const envelope = this.crypto.encrypt(combined);
 79→
 80→		const expiresAt = new Date(credentials.expires);
 81→
 82→		const conflictColumn = options.userId ? "user_id" : "team_id";
 83→		const result = await this.db.query(
 84→			`INSERT INTO oauth_credentials
 85→			 (user_id, team_id, provider, encrypted_dek, encrypted_refresh, encrypted_access, iv, expires_at, key_version)
 86→			 VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
 87→			 ON CONFLICT (${conflictColumn}, provider)
 88→			 DO UPDATE SET
 89→			   encrypted_dek = $4,
 90→			   encrypted_refresh = $5,
 91→			   encrypted_access = $6,
 92→			   iv = $7,
 93→			   expires_at = $8,
 94→			   key_version = $9,
 95→			   updated_at = now()
 96→			 RETURNING id`,
 97→			[
 98→				options.userId || null,
 99→				options.teamId || null,
100→				provider,
101→				envelope.encryptedDek,
102→				envelope.encryptedData,
103→				Buffer.alloc(0),
104→				envelope.iv,
105→				expiresAt,
106→				envelope.keyVersion,
107→			],
108→		);
109→
110→		// Audit log
111→		await this.db.query(
112→			`INSERT INTO oauth_audit_log (user_id, team_id, provider, action)
113→			 VALUES ($1, $2, $3, $4)`,
114→			[options.userId || null, options.teamId || null, provider, "store"],
115→		);
116→
117→		console.log(`[oauth-service] Stored credentials for provider=${provider}, id=${result.rows[0].id}`);
118→	}
119→
120→	/**
121→	 * Retrieve OAuth credentials for a user or team.
122→	 * Returns null if no credentials found.
123→	 */
124→	async getCredentials(
125→		provider: OAuthProviderId,
126→		options: { userId?: string; teamId?: string },
127→	): Promise<OAuthCredentials | null> {
128→		if (!options.userId && !options.teamId) {
129→			throw new Error("Either userId or teamId must be provided");
130→		}
131→
132→		const result = await this.db.query<OAuthCredentialRow>(
133→			`SELECT * FROM oauth_credentials
134→			 WHERE provider = $1
135→			   AND (user_id = $2 OR team_id = $3)
136→			 LIMIT 1`,
137→			[provider, options.userId || null, options.teamId || null],
138→		);
139→
140→		if (result.rows.length === 0) {
141→			return null;
142→		}
143→
144→		const row = result.rows[0];
145→
146→		// Decrypt combined token blob (stored in encrypted_refresh column)
147→		const combined = this.crypto.decrypt({
148→			encryptedDek: row.encrypted_dek,
149→			encryptedData: row.encrypted_refresh,
150→			iv: row.iv,
151→			keyVersion: row.key_version,
152→		});
153→
154→		const parsed = JSON.parse(combined) as OAuthCredentials;
155→
156→		return {
157→			...parsed,
158→			expires: row.expires_at.getTime(),
159→		};
160→	}
161→
162→	/**
163→	 * Get an API key from OAuth credentials, automatically refreshing if needed.
164→	 * Returns null if no credentials found.
165→	 */
166→	async getApiKey(
167→		provider: OAuthProviderId,
168→		options: { userId?: string; teamId?: string },
169→	): Promise<string | null> {
170→		const credentials = await this.getCredentials(provider, options);
171→		if (!credentials) {
172→			return null;
173→		}
174→
175→		// Use pi-ai's built-in refresh logic (expects a Record keyed by provider ID)
176→		const result = await getOAuthApiKey(provider, { [provider]: credentials });
177→		if (!result) {
178→			return null;
179→		}
180→
181→		// If credentials were refreshed, store the new ones
182→		if (result.newCredentials) {
183→			await this.storeCredentials(provider, result.newCredentials, options);
184→		}
185→
186→		return result.apiKey;
187→	}
188→
189→	/**
190→	 * Delete OAuth credentials for a user or team.
191→	 */
192→	async deleteCredentials(
193→		provider: OAuthProviderId,
194→		options: { userId?: string; teamId?: string },
195→	): Promise<boolean> {
196→		if (!options.userId && !options.teamId) {
197→			throw new Error("Either userId or teamId must be provided");
198→		}
199→
200→		const result = await this.db.query(
201→			`DELETE FROM oauth_credentials
202→			 WHERE provider = $1
203→			   AND (user_id = $2 OR team_id = $3)`,
204→			[provider, options.userId || null, options.teamId || null],
205→		);
206→
207→		if (result.rowCount && result.rowCount > 0) {
208→			// Audit log
209→			await this.db.query(
210→				`INSERT INTO oauth_audit_log (user_id, team_id, provider, action)
211→				 VALUES ($1, $2, $3, $4)`,
212→				[options.userId || null, options.teamId || null, provider, "delete"],
213→			);
214→			return true;
215→		}
216→
217→		return false;
218→	}
219→
220→	/**
221→	 * List all OAuth credentials for a user or team.
222→	 * Returns only metadata, not the actual credentials.
223→	 */
224→	async listCredentials(options: {
225→		userId?: string;
226→		teamId?: string;
227→	}): Promise<StoredOAuthCredential[]> {
228→		if (!options.userId && !options.teamId) {
229→			throw new Error("Either userId or teamId must be provided");
230→		}
231→
232→		const result = await this.db.query<OAuthCredentialRow>(
233→			`SELECT id, user_id, team_id, provider, expires_at, created_at, updated_at
234→			 FROM oauth_credentials
235→			 WHERE user_id = $1 OR team_id = $2
236→			 ORDER BY provider`,
237→			[options.userId || null, options.teamId || null],
238→		);
239→
240→		return result.rows.map((row) => ({
241→			id: row.id,
242→			userId: row.user_id,
243→			teamId: row.team_id,
244→			provider: row.provider,
245→			expiresAt: row.expires_at,
246→			createdAt: row.created_at,
247→			updatedAt: row.updated_at,
248→		}));
249→	}
250→}
