 1→import PromptDialog from "@mariozechner/mini-lit/dist/PromptDialog.js";
 2→import { i18n } from "./i18n.js";
 3→
 4→export async function getAuthToken(): Promise<string | undefined> {
 5→	let authToken: string | undefined = localStorage.getItem(`auth-token`) || "";
 6→	if (authToken) return authToken;
 7→
 8→	while (true) {
 9→		authToken = (
10→			await PromptDialog.ask(i18n("Enter Auth Token"), i18n("Please enter your auth token."), "", true)
11→		)?.trim();
12→		if (authToken) {
13→			localStorage.setItem(`auth-token`, authToken);
14→			break;
15→		}
16→	}
17→	return authToken?.trim() || undefined;
18→}
19→
20→export async function clearAuthToken() {
21→	localStorage.removeItem(`auth-token`);
22→}
