  1→/** Re-declare types locally to avoid importing server-side code into browser bundle */
  2→export interface AuthUser {
  3→  userId: string;
  4→  teamId: string;
  5→  email: string;
  6→  role: "admin" | "member";
  7→  displayName?: string;
  8→}
  9→
 10→export interface AuthResponse {
 11→  token: string;
 12→  user: {
 13→    id: string;
 14→    email: string;
 15→    displayName: string | null;
 16→    role: "admin" | "member";
 17→    teamId: string;
 18→    teamName: string;
 19→  };
 20→}
 21→
 22→export interface RegisterResponse {
 23→  message: string;
 24→  requiresVerification: boolean;
 25→}
 26→
 27→export interface RegistrationConfig {
 28→  mode: string;
 29→  turnstileSiteKey: string | null;
 30→}
 31→
 32→export class AuthClient {
 33→  private _token: string | null = null;
 34→  private _user: AuthUser | null = null;
 35→  private listeners = new Set<(user: AuthUser | null) => void>();
 36→  private _registrationConfig: RegistrationConfig | null = null;
 37→
 38→  constructor() {
 39→    // Restore from localStorage
 40→    this._token = localStorage.getItem("chatbot_token");
 41→    const userJson = localStorage.getItem("chatbot_user");
 42→    if (userJson) {
 43→      try { this._user = JSON.parse(userJson); } catch { this.clearStorage(); }
 44→    }
 45→  }
 46→
 47→  get token() { return this._token; }
 48→  get user() { return this._user; }
 49→  get isAuthenticated() { return !!this._token && !!this._user; }
 50→
 51→  /** Validate stored token by calling GET /api/auth/me */
 52→  async validate(): Promise<boolean> {
 53→    if (!this._token) return false;
 54→    try {
 55→      const res = await fetch("/api/auth/me", { headers: this.getHeaders() });
 56→      if (!res.ok) { this.clearStorage(); return false; }
 57→      return true;
 58→    } catch {
 59→      return false; // Network error, keep token (might be offline)
 60→    }
 61→  }
 62→
 63→  async login(email: string, password: string): Promise<AuthResponse> {
 64→    return this.postAuth("/api/auth/login", { email, password }, "Login failed");
 65→  }
 66→
 67→  async register(
 68→    email: string,
 69→    password: string,
 70→    displayName?: string,
 71→    teamName?: string,
 72→    inviteToken?: string,
 73→    turnstileToken?: string,
 74→  ): Promise<RegisterResponse> {
 75→    const res = await fetch("/api/auth/register", {
 76→      method: "POST",
 77→      headers: { "Content-Type": "application/json" },
 78→      body: JSON.stringify({ email, password, displayName, teamName, inviteToken, turnstileToken }),
 79→    });
 80→    const body = await res.json();
 81→    if (!res.ok) throw new Error(body.error || "Registration failed");
 82→    return body.data as RegisterResponse;
 83→  }
 84→
 85→  async resendVerification(email: string): Promise<void> {
 86→    await fetch("/api/auth/resend-verification", {
 87→      method: "POST",
 88→      headers: { "Content-Type": "application/json" },
 89→      body: JSON.stringify({ email }),
 90→    });
 91→  }
 92→
 93→  async getRegistrationConfig(): Promise<RegistrationConfig> {
 94→    if (this._registrationConfig) return this._registrationConfig;
 95→    const res = await fetch("/api/auth/registration-config");
 96→    this._registrationConfig = await res.json() as RegistrationConfig;
 97→    return this._registrationConfig;
 98→  }
 99→
100→  logout(): void {
101→    this.clearStorage();
102→    this.notify();
103→  }
104→
105→  getHeaders(): Record<string, string> {
106→    if (!this._token) return {};
107→    return { Authorization: `Bearer ${this._token}` };
108→  }
109→
110→  onAuthChange(callback: (user: AuthUser | null) => void): () => void {
111→    this.listeners.add(callback);
112→    return () => this.listeners.delete(callback);
113→  }
114→
115→  private async postAuth(url: string, payload: Record<string, unknown>, fallbackError: string): Promise<AuthResponse> {
116→    const res = await fetch(url, {
117→      method: "POST",
118→      headers: { "Content-Type": "application/json" },
119→      body: JSON.stringify(payload),
120→    });
121→    const body = await res.json();
122→    if (!res.ok) throw new Error(body.error || fallbackError);
123→    this.setAuth(body.data);
124→    return body.data;
125→  }
126→
127→  private setAuth(data: AuthResponse): void {
128→    this._token = data.token;
129→    this._user = {
130→      userId: data.user.id,
131→      teamId: data.user.teamId,
132→      email: data.user.email,
133→      role: data.user.role,
134→      displayName: data.user.displayName || undefined,
135→    };
136→    localStorage.setItem("chatbot_token", this._token);
137→    localStorage.setItem("chatbot_user", JSON.stringify(this._user));
138→    this.notify();
139→  }
140→
141→  private clearStorage(): void {
142→    this._token = null;
143→    this._user = null;
144→    localStorage.removeItem("chatbot_token");
145→    localStorage.removeItem("chatbot_user");
146→  }
147→
148→  private notify(): void {
149→    for (const cb of this.listeners) cb(this._user);
150→  }
151→}
